ount"],"state":{"timestamp":1656579373310440},"data":{"value":3}},{"keyPath":["syncMap","preferences","kix-ttsvn"],"state":{"timestamp":1790536414639708},"data":{"value":0}},{"keyPath":["syncMap","preferences","docs-should_display_disablement_callout"],"state":{"timestamp":1792754299143974},"data":{"value":true}}],  true , true , "t.0" , 1 , undefined , undefined , undefined , undefined , false , 0 , 0 , 0 ); DOCS_warmStartDocumentLoader = KX_kixApp.getWarmStartDocumentLoader(); DOCS_cseBlobArtifactsHolder = KX_kixApp.getCseBlobArtifactsHolder(); DOCS_initialLoadTiming = KX_kixApp.getInitialLoadTiming(); KX_getLatencyStats = function() {return KX_kixApp.getPerformanceManager().getInitialLoadStats();}; KX_resize = function() {KX_kixApp.resize();}; _docs_annotate_getAnnotatedText = function(id) {return KX_kixApp.getAnnotatedText(id);};}DOCS_timing['sac'] = new Date().getTime(); KX_startKix(); DOCS_initialLoadTiming.setTime('eac');</script><canvas width="1" height="500" style="display: none;"></canvas><span style="position: absolute; top: -999px; left: -999px;"></span><script nonce="">DOCS_warmStartDocumentLoader.startLoad( 1.0 ,'Z3sjdmoeP45naA', 2.147483647E9 , 0.0 ,[2147483647,"AAE\u003d"], 1.792754270002E12 , 1.0 ); var DOCS_modelChunkLoadStart; var DOCS_modelChunkParseStart; var DOCS_modelChunk;</script><script nonce="">DOCS_modelChunkParseStart = new Date().getTime();</script><script nonce="">DOCS_modelChunk = {"chunk":[{"ty":"is","ibi":1,"s":"#!/usr/bin/env bash\n\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\nTelegram Korcha - Complete Project Generator \u0026 ZIP Packager (Steps 1 to 7)\nRun: bash build_complete_zip.sh\n\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\u003d\nset -e\necho \"🚀 Assembling complete Telegram Korcha project (Steps 1 through 7)...\"\nmkdir -p src/components src/data migrations uploads dist\n------------------------------------------------------------------------------\n1. package.json\n------------------------------------------------------------------------------\ncat \u003c\u003c \u0027EOF\u0027 \u003e package.json { \"name\": \"telegram_korcha\", \"version\": \"1.0.0\", \"type\": \"module\", \"scripts\": { \"dev\": \"vite\", \"build\": \"vite build\", \"preview\": \"vite preview\", \"start\": \"node bot.js\" }, \"dependencies\": { \"dotenv\": \"^16.4.5\", \"express\": \"^4.19.2\", \"lucide-react\": \"^0.344.0\", \"multer\": \"^1.4.5-lts.1\", \"pg\": \"^8.11.5\", \"react\": \"^18.2.0\", \"react-dom\": \"^18.2.0\", \"telegraf\": \"^4.16.3\" }, \"devDependencies\": { \"@types/react\": \"^18.2.66\", \"@types/react-dom\": \"^18.2.22\", \"@vitejs/plugin-react\": \"^4.2.1\", \"autoprefixer\": \"^10.4.18\", \"postcss\": \"^8.4.35\", \"tailwindcss\": \"^3.4.1\", \"typescript\": \"^5.2.2\", \"vite\": \"^5.1.6\" } } EOF\n------------------------------------------------------------------------------\n2. .env.example\n------------------------------------------------------------------------------\ncat \u003c\u003c \u0027EOF\u0027 \u003e .env.example TELEGRAM_BOT_TOKEN\u003d\"your_bot_token_from_botfather\" TELEGRAM_WORKER_CHAT_ID\u003d\"your_numeric_telegram_chat_id\" WORKER_TELEGRAM_USERNAME\u003d\"korcha_support\" WORKER_USERNAMES\u003d\"korcha_support,admin_user\" TELEGRAM_WEB_APP_URL\u003d\"https://telegram.korcha.com.et\" PORT\u003d3000\nDATABASE_URL\u003d\"postgresql://korcha_user:korcha_password@localhost:5432/korcha_db\"\nHKD_EXCHANGE_RATE\u003d30.0 USD_TO_HKD\u003d7.8 KG_CARGO_RATE_ETB\u003d1000.0 ADVANCE_PAYMENT_PERCENT\u003d40 COD_PAYMENT_PERCENT\u003d60 EOF\n------------------------------------------------------------------------------\n3. Database Migrations (001, 002, 003)\n------------------------------------------------------------------------------\ncat \u003c\u003c \u0027EOF\u0027 \u003e migrations/001_initial_schema.sql CREATE TABLE IF NOT EXISTS customers ( id SERIAL PRIMARY KEY, telegram_id BIGINT UNIQUE, telegram_username VARCHAR(255), first_name VARCHAR(255), phone_number VARCHAR(32), created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP );\nCREATE TABLE IF NOT EXISTS quotes ( id SERIAL PRIMARY KEY, quote_code VARCHAR(32) UNIQUE NOT NULL, customer_id INTEGER REFERENCES customers(id) ON DELETE SET NULL, customer_phone VARCHAR(32) NOT NULL, source_type VARCHAR(32) NOT NULL, product_url TEXT, screenshot_url TEXT, size VARCHAR(64), color VARCHAR(64), quantity INTEGER DEFAULT 1, details TEXT, status VARCHAR(32) DEFAULT \u0027pending\u0027, quoted_price_etb NUMERIC(12, 2), deposit_required_etb NUMERIC(12, 2), assigned_worker VARCHAR(100), worker_response_note TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP );\nCREATE TABLE IF NOT EXISTS orders ( id SERIAL PRIMARY KEY, order_code VARCHAR(32) UNIQUE NOT NULL, quote_id INTEGER REFERENCES quotes(id) ON DELETE SET NULL, customer_phone VARCHAR(32) NOT NULL, product_summary TEXT, status VARCHAR(64) DEFAULT \u0027pending_deposit\u0027, total_price_etb NUMERIC(12, 2) NOT NULL, deposit_amount_etb NUMERIC(12, 2) NOT NULL, cod_balance_etb NUMERIC(12, 2) NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP ); EOF\ncat \u003c\u003c \u0027EOF\u0027 \u003e migrations/002_shelf_products.sql CREATE TABLE IF NOT EXISTS shelf_products ( id VARCHAR(64) PRIMARY KEY, title_am VARCHAR(255) NOT NULL, title_en VARCHAR(255), category VARCHAR(64) NOT NULL, price_etb NUMERIC(12, 2) NOT NULL, size VARCHAR(64), description TEXT, photo_file_id VARCHAR(255), image_url TEXT, stock_quantity INTEGER DEFAULT 1, in_stock BOOLEAN DEFAULT TRUE, badge VARCHAR(100) DEFAULT \u0027በእጅ ላይ ያለ (In Stock)\u0027, delivery_time VARCHAR(255) DEFAULT \u0027ዛሬውኑ ወይም በ24 ሰዓት ውስጥ ይረከቡ\u0027, added_by VARCHAR(100), created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP );\n"},{"ty":"as","st":"document","si":0,"ei":0,"sm":{"ds_df":{"df_dm":1}}},{"ty":"as","st":"headings","si":0,"ei":0,"sm":{"hs_h3":{"sdef_ps":{"ps_sb_i":false,"ps_sb":16.0},"sdef_ts":{"ts_ff_i":false,"ts_bd_i":false,"ts_ff":"Google Sans Text","ts_fgc2_i":false,"ts_fgc2":{"hclr_color":"#666666","clr_type":0},"ts_bd":false}},"hs_h2":{"sdef_ps":{"ps_sa_i":false,"ps_sa":6.0},"sdef_ts":{"ts_ff_i":false,"ts_bd_i":false,"ts_fs":16.0,"ts_ff":"Google Sans Text","ts_bd":false,"ts_fs_i":false}},"hs_h1":{"sdef_ps":{"ps_sb_i":false,"ps_sb":20.0},"sdef_ts":{"ts_ff_i":false,"ts_bd_i":false,"ts_fs":20.0,"ts_ff":"Google Sans Text;500","ts_bd":false,"ts_fs_i":false}},"hs_nt":{"sdef_ps":{"ps_lslm":1,"ps_sa_i":false,"ps_lslm_i":false,"ps_sm":0,"ps_sm_i":false,"ps_sa":10.0},"sdef_ts":{"ts_ff_i":false,"ts_ff":"Google Sans Text"}},"hs_h6":{"sdef_ps":{"ps_sb_i":false,"ps_sa_i":false,"ps_sa":4.0,"ps_sb":12.0},"sdef_ts":{"ts_ff_i":false,"ts_it":true,"ts_bd_i":false,"ts_ff":"Google Sans Text","ts_it_i":false,"ts_fgc2_i":false,"ts_fgc2":{"hclr_color":"#666666","clr_type":0},"ts_bd":false}},"hs_h5":{"sdef_ps":{"ps_sb_i":false,"ps_sa_i":false,"ps_sa":4.0,"ps_sb":12.0},"sdef_ts":{"ts_ff_i":false,"ts_bd_i":false,"ts_ff":"Google Sans Text","ts_fgc2_i":false,"ts_fgc2":{"hclr_color":"#66666